import{_ as t,o as a,a as l,b as i}from"./app.UgfkfLuP.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"概述","link":"/guide/technical_appendix/cpp_standard_support/overview"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/overview.md","filePath":"guide/technical_appendix/cpp_standard_support/overview.md","outlineHeaders":[{"level":2,"title":"语言标准的选择","slug":"语言标准的选择","link":"#语言标准的选择"},{"level":2,"title":"语言特性与限制导航","slug":"语言特性与限制导航","link":"#语言特性与限制导航"}],"lastUpdated":1793261337000}'),c={name:"guide/technical_appendix/cpp_standard_support/overview.md"};function d(r,e,n,p,s,o){return a(),l("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>概述</h1><p>本文介绍C/C++语言标准在Ascend C中的支持情况，包括语言标准的选择方式、Device侧的语法特性支持情况与使用约束，以及本章节的组织结构。Ascend C源文件由bisheng编译器编译，Host侧与Device侧代码在同一编译单元内统一处理，整体支持情况如下：</p><ul><li>Host侧与clang15一致，支持完整的C/C++标准。</li><li>Device侧支持C++11、C++14与C++17三档语言标准，默认按C++17编译。</li></ul><h2 id="语言标准的选择">语言标准的选择<a class="header-anchor" href="#语言标准的选择">​</a></h2><p>SIMD和SIMT编程场景均可通过<code>-std=c++&lt;version&gt;</code>或<code>--std=c++&lt;version&gt;</code>编译选项为编译单元指定C++语言标准。该选项启用所选标准的全部语言特性，并同时作用于Host侧与Device侧的编译过程。Device侧可选择的语言标准及对应编译选项如下：</p><ul><li>C++11（ISO/IEC 14882:2011）：<code>-std=c++11</code></li><li>C++14（ISO/IEC 14882:2014）：<code>-std=c++14</code></li><li>C++17（ISO/IEC 14882:2017）：<code>-std=c++17</code>，默认值</li></ul><p>Host侧与clang15一致，遵循其默认支持的语言标准范围。低于C++11的标准，如C++98、C++03，Device侧不支持。</p><p><strong>表1</strong> 语言标准的指定方式</p><table><thead><tr><th>指定方式</th><th>用法</th></tr></thead><tbody><tr><td>bisheng命令行编译</td><td>在编译命令中追加<code>-std=c++&lt;version&gt;</code></td></tr><tr><td>CMake工程</td><td>设置<code>CMAKE_ASC_STANDARD</code>变量</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>指定低于C++17的标准时，部分高版本语言特性会以clang扩展告警的形式继续可用，而非全部变为编译错误；需要严格限制语言版本时，可配合<code>-Werror</code>编译选项将此类告警升级为错误。</li><li>部分API接口内部实现依赖C++17标准，若指定低于C++17的标准，可能导致部分API无法使用。</li></ul></div><h2 id="语言特性与限制导航">语言特性与限制导航<a class="header-anchor" href="#语言特性与限制导航">​</a></h2><ul><li><strong><a href="./cpp_language_feature/cpp_language_feature.html">Device侧C++语言支持</a></strong>：C++语言特性在Device侧的支持情况。 <ul><li><a href="./cpp_language_feature/cpp11_language_feature.html">C++11语言特性</a>：C++11核心语言特性在Device侧的支持列表。</li><li><a href="./cpp_language_feature/cpp14_language_feature.html">C++14语言特性</a>：C++14语言特性在Device侧的支持列表。</li><li><a href="./cpp_language_feature/cpp17_language_feature.html">C++17语言特性</a>：C++17语言特性在Device侧的支持列表。</li><li><a href="./cpp_language_feature/lambda_expressions.html">Lambda表达式</a>：不同编程场景下Lambda表达式的使用方式与注意事项。</li></ul></li><li><strong><a href="./cpp_language_restrictions/cpp_language_restrictions.html">Device侧C/C++语法限制</a></strong>：Device侧通用的语法与能力限制。 <ul><li><a href="./cpp_language_restrictions/general_restrictions.html">C/C++通用语法限制</a>：指针与内存地址、变量、函数、类、模板等语法使用限制，含核函数参数列表限制、SIMT VF函数限制、SIMD与SIMT混合编程结构体使用限制。</li></ul></li></ul></article></div>',1)])])}const g=t(c,[["render",d]]);export{u as __pageData,g as default};
